const $=s=>document.querySelector(s);let active=examples[0];
function waveform(e){return `<svg viewBox="0 0 560 210"><line class="axis" x1="45" y1="175" x2="535" y2="175"/><line class="axis" x1="45" y1="20" x2="45" y2="175"/>${[75,125].map(y=>`<line class="gridline" x1="45" y1="${y}" x2="535" y2="${y}"/>`).join("")}<text class="wave-label" x="510" y="197">time</text><text class="wave-label" x="8" y="25">${e.wave.kind==="current"?"I":"V"}</text><path class="wave" d="M45 175 C62 174 72 45 112 38 C170 44 205 85 255 119 C330 158 430 172 535 175"/><path class="clamp" d="M45 175 C62 174 74 112 112 108 C190 109 285 145 535 175"/><text class="wave-value" x="118" y="29">${e.wave.peak}</text><text class="wave-label" x="120" y="103">TVS clamp</text><line class="gridline" x1="112" y1="38" x2="112" y2="175"/><text class="wave-label" x="87" y="192">1.2/8µs</text></svg>`}
function box(x,y,r,v){return `<g><rect class="partbox" x="${x-50}" y="${y-34}" width="100" height="68" rx="6"/><text class="ref" x="${x}" y="${y-4}">${r}</text><text class="value" x="${x}" y="${y+16}">${v}</text></g>`}function tvs(x,y,r,v){return `<g><rect class="tvsbox" x="${x-56}" y="${y-31}" width="112" height="62" rx="6"/><text class="ref" x="${x}" y="${y-4}">${r}</text><text class="value" x="${x}" y="${y+16}">${v}</text></g>`}function protect(x,y,r,v){return `<g><rect class="partbox" x="${x-55}" y="${y-34}" width="110" height="68" rx="6"/><text class="ref" x="${x}" y="${y-4}">${r}</text><text class="value" x="${x}" y="${y+16}">${v}</text></g>`}
function circuit(e){const power=e.topology!=="bus";return `<svg viewBox="0 0 1040 390"><defs><marker id="arr" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="#e9543f"/></marker></defs><path class="protectbox" d="M620 95H1010V285H620Z"/>${power?`<path class="wire" d="M45 190H190M290 190H410M510 190H650M750 190H930"/><path class="wire" d="M350 190V299M350 361V375"/><path class="surge" marker-end="url(#arr)" d="M35 145H90V190H350V365"/><text class="surge-label" x="35" y="130">SURGE IN</text>${box(240,190,"F1",e.parts[0][1])}${tvs(350,330,"D1",e.parts[1][1])}${box(460,190,"L1","π / EMI Filter")}${box(700,190,"U1",e.parts[2][1])}${protect(930,190,"LOAD",e.parts[3][1])}`:`<path class="wire" d="M45 165H235M45 225H235M335 165H465M335 225H465M565 195H720M820 195H960"/><path class="wire" d="M175 195V299M175 361V375"/><path class="surge" marker-end="url(#arr)" d="M25 120H75V165H175V365"/><text class="surge-label" x="25" y="105">8/20µs SURGE</text>${tvs(175,330,"D1","SM712-02HTG")}${box(285,195,"L1","Common-mode choke")}${box(515,195,"RT","120Ω / Split term.")}${box(770,195,"U1","THVD2450")}${protect(960,195,"MCU","UART / Logic")}`}<text class="node-label" x="40" y="255">CONNECTOR / FIELD SIDE</text><text class="node-label" x="640" y="120">RESIDUAL VOLTAGE DOMAIN</text></svg>`}
function render(e){active=e;$("#tabs").innerHTML=examples.map(x=>`<button class="${x.id===e.id?"active":""}" data-id="${x.id}">${x.tab}</button>`).join("");$("#tabs").querySelectorAll("button").forEach(b=>b.onclick=()=>render(examples.find(x=>x.id===b.dataset.id)));$("#category").textContent=e.category;$("#title").textContent=e.title;$("#application").textContent=e.application;$("#verdict").textContent=e.verdict;$("#wave-title").textContent=e.waveTitle;$("#wave-standard").textContent=e.standard;$("#waveform").innerHTML=waveform(e);$("#wave-facts").innerHTML=[["Peak",e.wave.peak],["Source",e.wave.source],["Pulse",e.wave.current]].map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join("");$("#vc").textContent=e.vc;$("#overshoot").textContent=e.overshoot;$("#residual").textContent=e.residual;$("#protected-part").textContent=e.part;$("#absmax").textContent=`${e.abs} V`;const pct=Math.min(100,e.remain/e.abs*100);$("#margin-bar i").style.width=`${pct}%`;$("#margin-bar em").style.left=`${pct}%`;$("#residual-note").textContent=e.note;$("#circuit").innerHTML=circuit(e);$("#parts").innerHTML=e.parts.map(x=>`<span><b>${x[0]}</b> · ${x[1]}</span>`).join("");$("#selected-model").textContent=e.model;$("#why-list").innerHTML=e.why.map(x=>`<li>${x}</li>`).join("");$("#alternatives").innerHTML=e.alts.map(x=>`<div class="alt"><b>${x[0]}</b><p>${x[1]}</p></div>`).join("");$("#assumption").textContent=e.assumption}render(active);
